import Foundation

/// Every job's action is materialized as a small zsh script, so cron and launchd
/// only ever need to invoke the run wrapper with a job id: no quoting of user
/// commands inside crontab lines or plists.
public enum ActionScript {
    static let appleScriptDelimiter = "CRONBUDDY_APPLESCRIPT"

    public static func render(_ job: Job) -> String {
        var lines = [
            "#!/bin/zsh",
            "# Generated by CronBuddy for “\(job.name.replacingOccurrences(of: "\n", with: " "))” (\(job.id)).",
            "# Edit the job in CronBuddy; changes here are overwritten.",
        ]
        for key in job.environment.keys.sorted() where Job.isValidEnvironmentName(key) {
            lines.append("export \(key)=\(Shell.quote(job.environment[key]!))")
        }
        switch job.action {
        case .shell(let command):
            lines.append(command)
        case .script(let path):
            lines.append("exec \(interpreter(for: path))\(Shell.quote(path)) \"$@\"")
        case .appleScript(let source):
            lines.append("/usr/bin/osascript <<'\(appleScriptDelimiter)'")
            lines.append(source)
            lines.append(appleScriptDelimiter)
        case .shortcut(let name):
            lines.append("exec /usr/bin/shortcuts run \(Shell.quote(name))")
        }
        return lines.joined(separator: "\n") + "\n"
    }

    static func interpreter(for path: String) -> String {
        switch (path as NSString).pathExtension.lowercased() {
        case "py": "/usr/bin/env python3 "
        case "sh", "bash": "/bin/bash "
        case "zsh": "/bin/zsh "
        case "rb": "/usr/bin/env ruby "
        case "pl": "/usr/bin/env perl "
        case "js", "jxa": "/usr/bin/osascript -l JavaScript "
        case "applescript", "scpt": "/usr/bin/osascript "
        case "workflow": "/usr/bin/automator "
        default: ""
        }
    }

    public static func write(_ job: Job, to url: URL) throws {
        try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
        try Data(render(job).utf8).write(to: url, options: .atomic)
        try FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: url.path)
    }
}

/// The wrapper cron and launchd invoke. It captures output, timing and exit
/// status of each run into the job's log folder, which the app watches.
public enum RunWrapper {
    public static let version = 1

    public static func render(paths: Paths) -> String {
        """
        #!/bin/zsh
        # CronBuddy run wrapper v\(version). Installed and overwritten by CronBuddy.
        zmodload zsh/datetime
        JOB_ID="$1"
        TRIGGER="${2:-schedule}"
        ACTION=\(Shell.quote(paths.actionsDir.path))/"$JOB_ID.sh"
        LOG_DIR=\(Shell.quote(paths.logs.path))/"$JOB_ID"
        mkdir -p "$LOG_DIR"
        export PATH="\(Paths.defaultPATH):$PATH"
        STAMP="$(strftime '%Y%m%d-%H%M%S' $EPOCHSECONDS)-$$"
        LOG="$LOG_DIR/$STAMP.log"
        START=$EPOCHREALTIME
        print -r -- "$$ $START" > "$LOG_DIR/.running"
        trap 'rm -f "$LOG_DIR/.running"' EXIT
        if [[ -x "$ACTION" ]]; then
          "$ACTION" > "$LOG" 2>&1 < /dev/null
          CODE=$?
        else
          print -r -- "CronBuddy: no action script at $ACTION" > "$LOG"
          CODE=127
        fi
        END=$EPOCHREALTIME
        print -r -- "{\\"start\\":$START,\\"end\\":$END,\\"exit\\":$CODE,\\"log\\":\\"$STAMP.log\\",\\"trigger\\":\\"$TRIGGER\\"}" >> "$LOG_DIR/runs.jsonl"
        exit $CODE

        """
    }

    public static func install(paths: Paths) throws {
        let url = paths.shim
        try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
        let contents = Data(render(paths: paths).utf8)
        if (try? Data(contentsOf: url)) != contents {
            try contents.write(to: url, options: .atomic)
        }
        try FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: url.path)
    }
}
